package com.mimtrix.libroenoc

data class VerseEntry(val reference: String, val text: String)
data class ChapterEntry(
    val number: Int,
    val title: String,
    val status: String,
    val editorialNote: String,
    val criticalNote: String,
    val verses: List<VerseEntry>
)

fun ChapterEntry.matchesQuery(query: String): Boolean {
    val q = query.trim()
    if (q.isEmpty()) return true
    return number.toString().contains(q, ignoreCase = true) ||
        title.contains(q, ignoreCase = true) ||
        status.contains(q, ignoreCase = true) ||
        editorialNote.contains(q, ignoreCase = true) ||
        criticalNote.contains(q, ignoreCase = true) ||
        verses.any { verse ->
            verse.reference.contains(q, ignoreCase = true) ||
                verse.text.contains(q, ignoreCase = true)
        }
}

object EnocContent {
    // Base de trabajo: traducción provisional. Cada versículo debe cotejarse con los testigos antes de declararse definitivo.
    val chapters = listOf(
        ChapterEntry(1, "Bendición y juicio", "Traducción revisada desde el ge'ez · aparato crítico en preparación",
            "Enoc pronuncia una bendición sobre los elegidos y los justos, y anuncia la manifestación del Santo, el estremecimiento de la creación, el juicio y la paz destinada a los justos.",
            "Base de trabajo: texto ge'ez de August Dillmann, Liber Henoch Aethiopice (1851), capítulo 1; traducción de R. H. Charles (1917); descripción del testigo Rylands Ethiopic MS 23, fol. 2r col. a, correspondiente al capítulo completo. La edición consultada advierte que el texto de Dillmann no es transcripción diplomática del códice y que Charles señala emendaciones y suplementos. Se conserva la numeración de Charles (1:1–9). En 1:4 no se incorpora al texto principal «y aparecer desde su campamento», que Charles imprime entre corchetes. En 1:7 Charles propone «por completo» como emendación; se deja fuera del texto principal hasta verificarla. En 1:8 se excluyen del cuerpo las frases que Charles marca como conjeturales («y él los ayudará a todos» / «y hará paz con ellos»). La puntuación y la disposición poética son editoriales. Pendiente: cotejo directo de fotografías del códice y de los aparatos de Charles 1906 y Knibb 1978; esta versión no se declara todavía edición crítica definitiva.",
            listOf(
                VerseEntry("1:1", "Palabras de la bendición de Enoc, con la que bendijo a los elegidos y a los justos que estarán presentes en el día de la tribulación, cuando sean apartados todos los malvados y los impíos."),
                VerseEntry("1:2", "Y comenzó a hablar en parábola y dijo: Enoc, hombre justo, cuyos ojos fueron abiertos por Dios, vio la visión del Santo en los cielos. Los ángeles me la mostraron; de ellos oí todo y por ellos comprendí lo que veía. Pero no para esta generación, sino para una generación lejana, venidera."),
                VerseEntry("1:3", "Acerca de los elegidos hablé y pronuncié mi parábola sobre ellos: El Santo y Grande saldrá de su morada."),
                VerseEntry("1:4", "El Dios eterno caminará sobre la tierra —sobre el monte Sinaí— y se manifestará; mostrará la fuerza de su poder desde el cielo."),
                VerseEntry("1:5", "Todos sentirán temor; los Vigilantes temblarán, y un gran miedo y estremecimiento se apoderarán de ellos hasta los confines de la tierra."),
                VerseEntry("1:6", "Las altas montañas serán sacudidas, las colinas elevadas se abatirán y se derretirán como cera ante la llama."),
                VerseEntry("1:7", "La tierra será desgarrada y todo cuanto hay sobre ella perecerá; habrá juicio sobre todos."),
                VerseEntry("1:8", "Pero con los justos establecerá la paz, protegerá a los elegidos y tendrá misericordia de ellos. Todos pertenecerán a Dios; prosperarán, serán bendecidos y la luz de Dios brillará para ellos."),
                VerseEntry("1:9", "Y he aquí que viene con miríadas de santos para ejecutar juicio, destruir a los impíos y pedir cuentas a toda carne por todas las obras de impiedad que cometieron y por todas las palabras duras que los pecadores impíos pronunciaron contra él.")
            )),
        ChapterEntry(2, "El orden de los cielos y de la tierra", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Observación del orden de las luminarias, la tierra y los ciclos estacionales como testimonio del orden creado.",
            "1. **Numeración.** Se conserva la división de Charles 1917: tres versículos. El texto ge'ez digital de Dillmann no lleva numeración versicular propia.\n2. **Versículo 2:1.** La traducción conserva la secuencia del ge'ez: observación de los fenómenos celestes, estabilidad de los caminos de las luminarias, salida y puesta en sus tiempos y obediencia al orden establecido. Charles añade entre corchetes angulares algunas palabras explicativas («y», según su sistema editorial); no se incorporan como palabras independientes en español.\n3. **Versículo 2:2.** El ge'ez transmite la invitación a mirar la tierra y considerar lo que ocurre en ella desde el comienzo hasta el fin, junto con una cláusula sobre la manifestación/regularidad de las obras de Dios. Charles presenta varias expresiones aclaratorias entre corchetes angulares («cómo permanecen firmes», «ninguna de las cosas sobre la tierra», «sino», «ante vosotros»). Se ha evitado convertir cada suplemento de su traducción en una lectura segura del original.\n4. **Versículo 2:3.** La frase sobre el agua, las nubes, el rocío y la lluvia aparece en el texto ge'ez de Dillmann. Charles la encierra en dobles corchetes angulares, señalando que la considera una adición secundaria en la tradición textual que traduce. Por eso se conserva aquí, pero esta nota advierte su condición discutida; no debe confundirse la presencia en el texto etiópico transmitido con la aceptación de su antigüedad en la forma más temprana del capítulo.\n5. **Testigo manuscrito.** La sección corresponde a Rylands Ethiopic MS 23, fol. 2r, columnas a–b, según el mapeo de la edición digital consultada. La propia fuente advierte que el ge'ez mostrado es la edición crítica de Dillmann (1851), no una transcripción diplomática del códice; la grafía del manuscrito puede diferir. Fuentes: - August Dillmann, *Liber Henoch Aethiopice* (Leipzig, 1851), capítulo 2, texto ge'ez.\n- R. H. Charles, *The Book of Enoch* (1917), 2:1–3; traducción basada en su edición crítica de 1906. Sus corchetes editoriales se registran arriba.\n- Theosis Library, “1 Enoch 1–36: The Book of the Watchers (Ethiopic)”, sección §2, con mapeo a Rylands Ethiopic MS 23, fol. 2r col. a–b y transcripción digital de Dillmann.\n- Online Critical Pseudepigrapha, lector digital de 1 Enoch: recurso para contrastar los testimonios griegos, latinos y los fragmentos arameos conservados (estos últimos incluidos hasta el capítulo 8 en el estado actual del proyecto). Documento editorial: docs/chapters/02.md",
            listOf(
                VerseEntry("2:1", "Observad todo cuanto sucede en el cielo: cómo las luminarias no se apartan de sus recorridos; cómo todas salen y se ponen ordenadamente, cada una en su tiempo, y no transgreden el orden que les ha sido asignado."),
                VerseEntry("2:2", "Contemplad la tierra y prestad atención a cuanto sucede sobre ella, desde el principio hasta su consumación: cómo todas las obras de Dios se manifiestan y permanecen en su orden."),
                VerseEntry("2:3", "Observad el verano y el invierno: la tierra se llena de agua, y las nubes, el rocío y la lluvia reposan sobre ella.")
            )),
        ChapterEntry(3, "Los árboles y sus hojas", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "- La tradición numerada por Charles presenta el capítulo como una sola unidad, sin subdivisión interna: 3:1.\n- El texto ge'ez de Dillmann contiene expresamente la excepción de catorce árboles y la conservación de las hojas viejas durante dos o tres años. No se debe omitir el número catorce ni convertirlo en una generalización botánica.\n- Charles introduce «durante el invierno» entre paréntesis y marca «parecen» como suplemento editorial. La traducción mantiene «parecen» como matiz explicativo, pero señala que no es una palabra inequívoca del texto base.\n- El manuscrito Rylands Ethiopic MS 23 sitúa el capítulo en fol. 2r, columna b. La edición ge'ez consultada es Dillmann 1851, no una transcripción diplomática del códice. Fuentes: August Dillmann, *Liber Henoch Aethiopice* (1851), cap. 3; R. H. Charles, *The Book of Enoch* (1917), 3:1; Theosis Library, §3, con referencia al Rylands Ethiopic MS 23, fol. 2r col. b. Documento editorial: docs/chapters/03.md",
            listOf(
                VerseEntry("3:1", "Observad y ved cómo, durante el invierno, todos los árboles parecen marchitarse y pierden sus hojas, excepto catorce árboles que no pierden su follaje, sino que conservan las hojas antiguas durante dos o tres años, hasta que brotan las nuevas.")
            )),
        ChapterEntry(4, "El calor del verano", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "- Charles transmite el capítulo como un solo versículo, 4:1; se conserva esa unidad.\n- El ge'ez de Dillmann contiene la secuencia completa: posición del sol sobre la tierra, búsqueda de sombra y cobijo, calor que abrasa la tierra e imposibilidad de pisarla o pisar una roca por el calor.\n- La expresión «frente a ella» traduce la relación espacial del texto; no se interpreta como una afirmación astronómica moderna.\n- Rylands Ethiopic MS 23, fol. 2r, columna b, contiene este capítulo. La puntuación y la división en frases son editoriales. Fuentes: August Dillmann, *Liber Henoch Aethiopice* (1851), cap. 4; R. H. Charles, *The Book of Enoch* (1917), 4:1; Theosis Library, §4, Rylands Ethiopic MS 23, fol. 2r col. b. Documento editorial: docs/chapters/04.md",
            listOf(
                VerseEntry("4:1", "Y nuevamente, observad los días del verano: el sol se encuentra sobre la tierra, frente a ella. Vosotros buscáis sombra y refugio a causa del calor del sol; también la tierra arde con un calor intenso, y no podéis caminar sobre la tierra ni sobre una roca debido a su ardor.")
            )),
        ChapterEntry(5, "La creación persevera; los seres humanos se apartan", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "1. **Estructura.** Se conserva la numeración peculiar de Charles. El capítulo no puede reducirse a nueve versículos corridos sin ocultar sus subdivisiones: Charles imprime 5:6a–g, luego 5:6i–j y 5:7a–b. La omisión de la letra h en la secuencia reproducida es editorial y debe verificarse antes de reconstruirla.\n2. **5:1–3.** El texto ge'ez describe los árboles, la continuidad anual de las obras y la acción conjunta de mares y ríos. Las expresiones entre corchetes angulares de Charles («y conoced», «sus obras», «para siempre», «y no cambian») son aclaraciones editoriales; no todas se han reproducido como palabras independientes.\n3. **5:4–5.** La exhortación y la maldición contra los transgresores están presentes en el ge'ez. En 5:5 Charles ofrece una formulación extensa sobre los años de destrucción; la traducción mantiene su sentido sin convertir la imagen en una cifra cronológica.\n4. **5:6–7.** Es el pasaje más inestable del capítulo. Charles imprime una secuencia con letras y signos no continuos y coloca parte del material entre corchetes angulares. No se ha fabricado un versículo h ni se ha incorporado la sección marcada como si su posición y lectura fueran seguras. El resumen entre corchetes de 5:6d–g es una descripción editorial, no una traducción literal; por ello este segmento no se considera texto español final y deberá cotejarse con la edición ge'ez de 23 manuscritos de Charles y los testigos paralelos.\n5. **5:8–9.** La promesa a los elegidos y su vida en paz se conserva en la secuencia de Charles. La puntuación y la disposición poética son editoriales. Fuentes: August Dillmann, *Liber Henoch Aethiopice* (1851), cap. 5; R. H. Charles, *The Book of Enoch* (1917), 5:1–9 con subdivisiones alfabéticas; Theosis Library, §5, Rylands Ethiopic MS 23, fol. 2r cols. b–c. Documento editorial: docs/chapters/05.md",
            listOf(
                VerseEntry("5:1", "Observad cómo los árboles se cubren de hojas verdes y producen frutos. Prestad atención a todas sus obras y reconoced que el Viviente eterno las ha dispuesto de ese modo."),
                VerseEntry("5:2", "Todas sus obras continúan así de año en año y por siempre; cumplen las tareas que les han sido asignadas y no alteran su curso. Todo sucede conforme a lo que Dios ha ordenado."),
                VerseEntry("5:3", "Ved también cómo los mares y los ríos cumplen juntos sus funciones y no se apartan de lo que les ha sido mandado."),
                VerseEntry("5:4", "Pero vosotros no habéis permanecido firmes ni habéis cumplido los mandamientos del Señor. Os habéis apartado y habéis pronunciado palabras orgullosas y duras con vuestras bocas impuras contra su grandeza. ¡Duros de corazón! No encontraréis paz."),
                VerseEntry("5:5", "Por eso maldeciréis vuestros días; los años de vuestra vida desaparecerán y aumentarán los años de vuestra destrucción bajo una maldición eterna. No hallaréis misericordia."),
                VerseEntry("5:6a", "En aquellos días haréis de vuestros nombres una maldición eterna para todos los justos."),
                VerseEntry("5:6b", "Por causa de vosotros, todos los que maldigan pronunciarán maldición."),
                VerseEntry("5:6c", "Y todos los pecadores y los impíos os tomarán como fórmula de imprecación."),
                VerseEntry("5:6d–g", "[La secuencia siguiente contiene una sección de texto transmitido de forma irregular y marcada por Charles con signos editoriales: habla de la alegría de los justos, el perdón de los pecados, la misericordia, la paz, la paciencia y la salvación como luz favorable.]"),
                VerseEntry("5:6i–j", "[La continuación de esa sección afirma que no habrá salvación para los pecadores y que la maldición permanecerá sobre ellos.]"),
                VerseEntry("5:7a", "Pero para los elegidos habrá luz, gracia y paz."),
                VerseEntry("5:7b", "Ellos heredarán la tierra."),
                VerseEntry("5:8", "Entonces se concederá sabiduría a los elegidos; todos vivirán y no volverán a pecar, ni por impiedad ni por orgullo. Quienes poseen sabiduría serán humildes."),
                VerseEntry("5:9", "No volverán a transgredir ni pecarán durante todos los días de su vida; no morirán por la ira o el furor divinos, sino que completarán el número de los días de su vida. Sus vidas se prolongarán en paz, sus años de alegría se multiplicarán en gozo y paz eternos, durante todos los días de su existencia.")
            )),
        ChapterEntry(6, "El descenso de los Vigilantes", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "Charles numera 6:1–8. En 6:6, «en los días de Jared» aparece como suplemento editorial entre signos angulares; no se incorpora como lectura segura del ge'ez de Dillmann. La lista de nombres presenta diferencias de forma y orden entre transcripciones y testigos; las formas españolas son normalizaciones de lectura, no equivalencias fonéticas definitivas. La frase «hijos del cielo» se conserva según la versión etiópica. Rylands Ethiopic MS 23, fol. 2r col. c. Fuentes: Dillmann 1851, cap. 6; Charles 1917, 6:1–8; Theosis Library, §6, Rylands Ethiopic MS 23, fol. 2r col. c. Pendiente cotejo de los 23 manuscritos de Charles 1906 y Knibb. Documento editorial: docs/chapters/06.md",
            listOf(
                VerseEntry("6:1", "Cuando los hijos de los hombres se multiplicaron, en aquellos días nacieron hijas hermosas y agraciadas."),
                VerseEntry("6:2", "Los ángeles, hijos del cielo, las vieron, las desearon y se dijeron: «Venid, escojamos mujeres entre las hijas de los hombres y engendremos hijos»."),
                VerseEntry("6:3", "Semihazá, su jefe, les dijo: «Temo que quizá no queráis realizar esta acción y que yo solo tenga que responder por este gran pecado»."),
                VerseEntry("6:4", "Todos le respondieron: «Juremos juntos y comprometámonos mediante una maldición recíproca a no abandonar este propósito, sino a llevarlo a cabo»."),
                VerseEntry("6:5", "Entonces todos juraron juntos y se comprometieron unos con otros mediante aquella maldición."),
                VerseEntry("6:6", "Eran doscientos. Descendieron sobre la cima del monte Hermón —en los días de Jared, según el suplemento de Charles— y lo llamaron Hermón porque allí habían jurado y se habían comprometido mediante una maldición."),
                VerseEntry("6:7", "Estos son los nombres de sus jefes: Semihazá, su dirigente; Arakiba, Rameel, Kokabiel, Tamiel, Ramiel, Daniel, Ezequiel, Baraqiel, Asael, Armaros, Batariel, Ananel, Zaqiel, Samsapeel, Satariel, Turel, Yomiel y Sariel."),
                VerseEntry("6:8", "Estos eran los jefes de decenas de todos ellos.")
            )),
        ChapterEntry(7, "Los gigantes y la violencia", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "Charles 7:3–4 presenta una ruptura sintáctica: la frase «cuando los hombres ya no pudieron sostenerlos» completa la idea iniciada en 7:3. Se conserva la división editorial de Charles. La cifra «tres mil codos» es una lectura transmitida extraordinaria; no se corrige ni se convierte a una medida moderna. Rylands Ethiopic MS 23, fol. 2r col. c–2v col. a. Fuentes: Dillmann 1851, cap. 7; Charles 1917, 7:1–6; Theosis Library, §7, Rylands Ethiopic MS 23, fol. 2r col. c–2v col. a. Pendiente cotejo de variantes y de la unidad de medida. Documento editorial: docs/chapters/07.md",
            listOf(
                VerseEntry("7:1", "Los demás, junto con ellos, tomaron mujeres; cada uno escogió una para sí. Comenzaron a acercarse a ellas y a unirse con ellas, y les enseñaron encantamientos, conjuros, el corte de raíces y el conocimiento de las plantas."),
                VerseEntry("7:2", "Las mujeres concibieron y dieron a luz grandes gigantes, cuya estatura era de tres mil codos."),
                VerseEntry("7:3", "Los gigantes consumieron todas las posesiones y los recursos que los seres humanos habían producido."),
                VerseEntry("7:4", "Cuando los hombres ya no pudieron sostenerlos, los gigantes se volvieron contra ellos y devoraron a la humanidad."),
                VerseEntry("7:5", "Comenzaron a pecar contra las aves, las bestias, los reptiles y los peces; se devoraban unos a otros y bebían sangre."),
                VerseEntry("7:6", "Entonces la tierra presentó una acusación contra los transgresores.")
            )),
        ChapterEntry(8, "Las enseñanzas de los Vigilantes", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "En 8:1 Charles marca «de la tierra» como suplemento. En 8:3 la lista de Araqiel y Shamsiel aparece entre corchetes angulares en Charles: se conserva aquí entre corchetes editoriales porque su condición es discutida, no como lectura indiscutida. Los nombres de maestros y las atribuciones varían. Rylands Ethiopic MS 23, fol. 2v col. a. Fuentes: Dillmann 1851, cap. 8; Charles 1917, 8:1–4; Theosis Library, §8, Rylands Ethiopic MS 23, fol. 2v col. a. Pendiente cotejo de la lista con los testigos griegos y arameos disponibles. Documento editorial: docs/chapters/08.md",
            listOf(
                VerseEntry("8:1", "Azazel enseñó a los hombres a fabricar espadas, cuchillos, escudos y corazas. Les mostró los metales de la tierra y el modo de trabajarlos; también les enseñó a fabricar brazaletes y adornos, el uso del antimonio, el embellecimiento de los párpados, las piedras preciosas y toda clase de tintes."),
                VerseEntry("8:2", "Se extendió una gran impiedad; cometieron inmoralidades, fueron desviados y se corrompieron en todos sus caminos."),
                VerseEntry("8:3", "Semihazá enseñó encantamientos y el corte de raíces; Armaros, cómo deshacer encantamientos; Baraqiel, la astrología; Kokabiel, las constelaciones; Ezequiel, el conocimiento de las nubes; Araqiel, los signos de la tierra; Shamsiel, los signos del sol; y Sariel, el curso de la luna."),
                VerseEntry("8:4", "Mientras los seres humanos perecían, clamaban, y su clamor subió hasta el cielo.")
            )),
        ChapterEntry(9, "La súplica de los arcángeles", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "En 9:2 Charles marca con † una expresión de difícil interpretación («hecha sin habitantes, clama la voz de su clamor»). La traducción ofrece una lectura inteligible sin ocultar la dificultad. En 9:3 la invocación inicial está entre dobles corchetes angulares y se señala como suplemento. En 9:4 Charles añade entre signos angulares «y Dios de los siglos»; no se incorpora al texto principal. El orden de los cuatro arcángeles difiere en el ge'ez de Dillmann respecto de la secuencia normalizada en algunas traducciones. Rylands Ethiopic MS 23, fol. 2v cols. a–b. Fuentes: Dillmann 1851, cap. 9; Charles 1917, 9:1–11; Theosis Library, §9, Rylands Ethiopic MS 23, fol. 2v cols. a–b. Pendiente cotejo de la cláusula marcada † y de los fragmentos griegos. Documento editorial: docs/chapters/09.md",
            listOf(
                VerseEntry("9:1", "Entonces Miguel, Uriel, Rafael y Gabriel miraron desde el cielo y vieron la abundante sangre derramada sobre la tierra y toda la injusticia que allí se cometía."),
                VerseEntry("9:2", "Se dijeron unos a otros: «La tierra, privada de habitantes, hace llegar el clamor de sus voces hasta las puertas del cielo»."),
                VerseEntry("9:3", "[«Y ahora, a vosotros, santos del cielo»:] las almas de los seres humanos presentan su súplica y dicen: «Llevad nuestra causa ante el Altísimo»."),
                VerseEntry("9:4", "Y dijeron al Señor de los siglos: «Señor de los señores, Dios de los dioses, Rey de los reyes: tu trono glorioso permanece por todas las generaciones. Tu nombre es santo, glorioso y bendito por todos los siglos»."),
                VerseEntry("9:5", "«Tú has hecho todas las cosas y tienes autoridad sobre todas ellas. Todo está descubierto y manifiesto ante tu mirada; todo lo ves y nada puede ocultarse de ti»."),
                VerseEntry("9:6", "«Has visto lo que ha hecho Azazel: ha enseñado toda injusticia sobre la tierra y ha revelado los secretos eternos que estaban guardados en el cielo y que los seres humanos procuraban conocer»."),
                VerseEntry("9:7", "«También has visto a Semihazá, a quien diste autoridad sobre sus compañeros»."),
                VerseEntry("9:8", "«Ellos fueron juntos a las hijas de los hombres, se unieron a ellas, se contaminaron y les revelaron toda clase de pecados»."),
                VerseEntry("9:9", "«Las mujeres dieron a luz gigantes, y por ello toda la tierra se llenó de sangre e injusticia»."),
                VerseEntry("9:10", "«Ahora, mira: las almas de quienes han muerto claman y presentan su súplica hasta las puertas del cielo; sus lamentos han subido y no pueden cesar a causa de las injusticias cometidas sobre la tierra»."),
                VerseEntry("9:11", "«Tú conoces todas las cosas antes de que sucedan; ves esto y lo permites, pero no nos has indicado qué debemos hacer con ellos».")
            )),
        ChapterEntry(10, "Las sentencias contra los Vigilantes", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "Charles marca suplementos importantes: «ve a Noé» en 10:2; cláusulas en 10:9; «que sea bendición...» en 10:16; y la frase inicial de 10:21. Se conservan entre corchetes y no se presentan como lectura segura. La misión de Uriel al «hijo de Lamec» y la identificación de Noé se relacionan mediante suplemento editorial. Rylands Ethiopic MS 23, fol. 2v col. b–3r col. a. Fuentes: Dillmann 1851, cap. 10; Charles 1917, 10:1–22; Theosis Library, §10, Rylands Ethiopic MS 23, fol. 2v col. b–3r col. a. Pendiente aparato completo de Charles 1906 y comparación de los testigos arameos/griegos pertinentes. Documento editorial: docs/chapters/10.md",
            listOf(
                VerseEntry("10:1", "Entonces habló el Altísimo, el Santo y Grande, y envió a Uriel al hijo de Lamec."),
                VerseEntry("10:2", "Le dijo: «[Ve a Noé y] anúnciale en mi nombre: “Escóndete”. Revela el final que se aproxima: toda la tierra será destruida; viene un diluvio sobre ella y destruirá cuanto exista en su superficie»."),
                VerseEntry("10:3", "«Instrúyelo para que escape y para que su descendencia sea preservada a través de todas las generaciones del mundo»."),
                VerseEntry("10:4", "Después el Señor dijo a Rafael: «Ata a Azazel de pies y manos y arrójalo a las tinieblas. Abre una cavidad en el desierto de Dudael y échalo allí»."),
                VerseEntry("10:5", "«Coloca sobre él piedras ásperas y puntiagudas; cúbrelo de oscuridad y déjalo allí para siempre. Cubre su rostro para que no vea la luz»."),
                VerseEntry("10:6", "«En el día del gran juicio será arrojado al fuego»."),
                VerseEntry("10:7", "«Sana la tierra que los ángeles corrompieron y anuncia su curación, para que se remedie la plaga y los seres humanos no perezcan por los secretos que los Vigilantes revelaron y enseñaron a sus hijos»."),
                VerseEntry("10:8", "«Toda la tierra ha sido corrompida por las obras que Azazel enseñó. A él atribúyase toda culpa»."),
                VerseEntry("10:9", "El Señor dijo a Gabriel: «Ve contra los bastardos, los réprobos y los hijos de la transgresión; destruye a los hijos de los Vigilantes de entre los seres humanos. [Haz que salgan y] envíalos unos contra otros para que se destruyan en combate, pues no tendrán larga vida»."),
                VerseEntry("10:10", "«No se concederá a sus padres ninguna petición en favor de ellos, pues esperan vivir eternamente y que cada uno alcance quinientos años»."),
                VerseEntry("10:11", "El Señor dijo a Miguel: «Ve y ata a Semihazá y a sus compañeros, que se unieron a las mujeres y se contaminaron con ellas en toda su impureza»."),
                VerseEntry("10:12", "«Cuando sus hijos se hayan matado entre sí y ellos hayan visto la destrucción de sus seres queridos, átalos durante setenta generaciones en los valles de la tierra, hasta el día de su juicio y de su consumación, hasta que se complete el juicio eterno»."),
                VerseEntry("10:13", "«En aquellos días serán conducidos al abismo de fuego, al tormento y a la prisión donde permanecerán encerrados para siempre»."),
                VerseEntry("10:14", "«Quien sea condenado y destruido quedará desde entonces ligado a ellos hasta el fin de todas las generaciones»."),
                VerseEntry("10:15", "«Destruye todos los espíritus de los réprobos y a los hijos de los Vigilantes, porque hicieron daño a la humanidad»."),
                VerseEntry("10:16", "«Haz desaparecer toda injusticia de la faz de la tierra y pon fin a toda obra malvada. Que aparezca la planta de la justicia y de la verdad; [que sea bendición y que] sus obras sean plantadas para siempre en verdad y alegría»."),
                VerseEntry("10:17", "«Entonces todos los justos escaparán y vivirán hasta engendrar miles de hijos; completarán en paz todos los días de su juventud y de su vejez»."),
                VerseEntry("10:18", "«En aquellos días toda la tierra será cultivada con justicia y quedará plantada de árboles; se llenará de bendición»."),
                VerseEntry("10:19", "«Se plantarán en ella árboles agradables y viñas. La vid dará vino en abundancia; cada medida de semilla sembrada producirá mil medidas, y una medida de aceitunas dará diez medidas de aceite»."),
                VerseEntry("10:20", "«Purifica la tierra de toda opresión, injusticia, pecado e impiedad; elimina de ella toda impureza que se comete sobre su superficie»."),
                VerseEntry("10:21", "«[Que todos los hijos de los hombres lleguen a ser justos,] y que todas las naciones me adoren, me bendigan y se inclinen ante mí»."),
                VerseEntry("10:22", "«La tierra quedará purificada de toda corrupción, pecado, castigo y tormento. Nunca más enviaré estas cosas sobre ella, de generación en generación y para siempre».")
            )),
        ChapterEntry(11, "Los depósitos de bendición", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "Charles imprime «sobre la tierra» entre signos angulares como suplemento. Se señala aquí como aclaración editorial, no como elemento indiscutible del texto. El capítulo tiene dos versículos en Charles y ocupa Rylands Ethiopic MS 23, fol. 3r col. a. Fuentes: Dillmann 1851, cap. 11; Charles 1917, 11:1–2; Theosis Library, §11, Rylands Ethiopic MS 23, fol. 3r col. a. Documento editorial: docs/chapters/11.md",
            listOf(
                VerseEntry("11:1", "En aquellos días abriré los depósitos de bendición que están en el cielo y los haré descender sobre la tierra, sobre las obras y el trabajo de los hijos de los hombres."),
                VerseEntry("11:2", "La paz y la verdad estarán unidas durante todos los días del mundo y a través de todas las generaciones de los seres humanos.")
            )),
        ChapterEntry(12, "Enoc recibe la misión", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "La sintaxis de 12:5–6 es difícil y Charles marca con † pronombres y términos de lectura incierta. La traducción conserva el discurso continuo sin ocultar que la relación entre «ellos», «sus hijos» y «vuestros hijos» necesita cotejo. Rylands Ethiopic MS 23, fol. 3r col. a. Fuentes: Dillmann 1851, cap. 12; Charles 1917, 12:1–6; Theosis Library, §12, Rylands Ethiopic MS 23, fol. 3r col. a. Documento editorial: docs/chapters/12.md",
            listOf(
                VerseEntry("12:1", "Antes de estos acontecimientos, Enoc había sido ocultado, y ninguno de los hijos de los hombres sabía dónde estaba, dónde habitaba ni qué había sido de él."),
                VerseEntry("12:2", "Sus actividades estaban relacionadas con los Vigilantes, y sus días transcurrían con los santos."),
                VerseEntry("12:3", "Yo, Enoc, bendecía al Señor de la majestad y Rey de los siglos, cuando los Vigilantes me llamaron —a mí, Enoc el escriba— y me dijeron:"),
                VerseEntry("12:4", "«Enoc, escriba de justicia, ve y anuncia a los Vigilantes del cielo que abandonaron el cielo elevado y el lugar santo y eterno, que se contaminaron con mujeres, hicieron lo mismo que los hijos de la tierra y tomaron mujeres para sí: “Habéis causado una gran destrucción sobre la tierra”»."),
                VerseEntry("12:5", "«No tendréis paz ni perdón de pecado; puesto que os complacéis en vuestros hijos…»"),
                VerseEntry("12:6", "«Veréis la muerte de vuestros seres queridos, lamentaréis la destrucción de vuestros hijos y suplicaréis eternamente; pero no alcanzaréis misericordia ni paz».")
            )),
        ChapterEntry(13, "La petición de los Vigilantes", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "En 13:2 Charles marca con † el término traducido como «petición»; en 13:6 la oración sobre los espíritus, las acciones y la extensión de los días también contiene signos de incertidumbre. En 13:8 la orden vocal está entre corchetes angulares. Los topónimos de 13:7 y 13:9 tienen variantes de transliteración. Rylands Ethiopic MS 23, fol. 3r cols. a–b. Fuentes: Dillmann 1851, cap. 13; Charles 1917, 13:1–10; Theosis Library, §13, Rylands Ethiopic MS 23, fol. 3r cols. a–b. Documento editorial: docs/chapters/13.md",
            listOf(
                VerseEntry("13:1", "Enoc fue y dijo a Azazel: «No tendrás paz; ha salido contra ti una sentencia severa para ponerte en cadenas»."),
                VerseEntry("13:2", "«No se te concederá tolerancia ni petición alguna, a causa de la injusticia que enseñaste y de todas las obras de impiedad, injusticia y pecado que mostraste a los seres humanos»."),
                VerseEntry("13:3", "Entonces fui y hablé a todos juntos. Todos sintieron temor, y el miedo y el estremecimiento se apoderaron de ellos."),
                VerseEntry("13:4", "Me suplicaron que redactara para ellos una petición, a fin de que pudieran obtener perdón, y que presentara su súplica ante el Señor del cielo."),
                VerseEntry("13:5", "Desde entonces no podían hablar con él ni levantar los ojos al cielo, avergonzados por los pecados por los que habían sido condenados."),
                VerseEntry("13:6", "Entonces escribí su petición y la súplica relativa a sus espíritus, a cada una de sus acciones y a su deseo de recibir perdón y prolongación de sus días."),
                VerseEntry("13:7", "Me alejé y me senté junto a las aguas de Dan, en la tierra de Dan, al suroeste del Hermón. Leí su petición hasta que me quedé dormido."),
                VerseEntry("13:8", "Y he aquí que me sobrevino un sueño y cayeron sobre mí visiones. Vi visiones de castigo [y una voz me ordenó] que las anunciara a los hijos del cielo y los reprendiera."),
                VerseEntry("13:9", "Cuando desperté, fui hacia ellos. Estaban reunidos y lloraban en Abel-Selsal, entre el Líbano y Seneser, con los rostros cubiertos."),
                VerseEntry("13:10", "Les relaté todas las visiones que había visto durante el sueño y comencé a pronunciar palabras de justicia y a reprender a los Vigilantes celestiales.")
            )),
        ChapterEntry(14, "La visión del trono celestial", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "El capítulo contiene una visión extensa y varias cláusulas marcadas por Charles como suplementos o reconstrucciones. En 14:3 la explicación de la capacidad de comprender contiene una adición editorial; en 14:4 Charles añade una cláusula extensa entre corchetes angulares; en 14:5 «en cadenas» es suplemento; en 14:8 la orden de una voz es suplemento; en 14:18 «en ella» es aclaración; en 14:25 la intervención de uno de los santos aparece entre corchetes angulares. Se indican aquí sin elevarlas a texto seguro. Rylands Ethiopic MS 23, fol. 3r col. b–3v col. a. Fuentes: Dillmann 1851, cap. 14; Charles 1917, 14:1–25; Theosis Library, §14, Rylands Ethiopic MS 23, fol. 3r col. b–3v col. a. Pendiente cotejo detallado de la visión con las ediciones críticas y testigos griegos. Documento editorial: docs/chapters/14.md",
            listOf(
                VerseEntry("14:1", "Este es el libro de las palabras de justicia y de la reprensión de los Vigilantes eternos, conforme al mandato del Santo y Grande en aquella visión."),
                VerseEntry("14:2", "Vi durante el sueño lo que ahora diré con lengua humana y con el aliento de mi boca, que el Grande ha dado a los hombres para hablar y comprender con el corazón."),
                VerseEntry("14:3", "Así como creó y concedió al ser humano la capacidad de comprender la palabra de sabiduría, también me creó y me concedió la capacidad de reprender a los Vigilantes, hijos del cielo."),
                VerseEntry("14:4", "Escribí vuestra petición, pero en mi visión se me mostró que no os será concedida; el juicio ha sido pronunciado contra vosotros."),
                VerseEntry("14:5", "Desde ahora no subiréis al cielo por toda la eternidad; ha salido la sentencia de manteneros atados sobre la tierra durante todos los días del mundo."),
                VerseEntry("14:6", "Antes veréis la destrucción de vuestros hijos amados; no hallaréis alegría en ellos, pues caerán ante vosotros por la espada."),
                VerseEntry("14:7", "No se concederá vuestra petición en favor de ellos ni en favor de vosotros, aunque lloréis, supliquéis y pronunciéis todas las palabras del escrito que redacté."),
                VerseEntry("14:8", "La visión se me mostró así: las nubes me llamaron, la niebla me convocó, el curso de las estrellas y los relámpagos me impulsaron con rapidez, y los vientos de la visión me elevaron y me llevaron al cielo."),
                VerseEntry("14:9", "Entré hasta acercarme a un muro construido de cristales y rodeado de lenguas de fuego; aquello comenzó a infundirme temor."),
                VerseEntry("14:10", "Atravesé las lenguas de fuego y me acerqué a una gran casa construida de cristales. Sus paredes parecían un pavimento de mosaicos de cristal y su suelo era de cristal."),
                VerseEntry("14:11", "Su techo era como el camino de las estrellas y de los relámpagos; entre ellos había querubines de fuego, y el cielo que los cubría era como agua."),
                VerseEntry("14:12", "Un fuego ardiente rodeaba las paredes y sus puertas resplandecían con llamas."),
                VerseEntry("14:13", "Entré en aquella casa. Era caliente como el fuego y fría como el hielo; no había allí deleite de vida. El temor me cubrió y el temblor se apoderó de mí."),
                VerseEntry("14:14", "Mientras temblaba, caí rostro en tierra y contemplé una visión."),
                VerseEntry("14:15", "Y he aquí una segunda casa, mayor que la primera; toda su entrada estaba abierta ante mí y estaba construida con llamas de fuego."),
                VerseEntry("14:16", "En todo superaba a la primera en esplendor, magnificencia y extensión; no puedo describiros su esplendor ni sus dimensiones."),
                VerseEntry("14:17", "Su suelo era de fuego; por encima estaban los relámpagos y el camino de las estrellas, y también su techo era de fuego ardiente."),
                VerseEntry("14:18", "Miré y vi en ella un trono elevado, cuyo aspecto era como cristal y cuyas ruedas brillaban como el sol; había allí una visión de querubines."),
                VerseEntry("14:19", "De debajo del trono salían corrientes de fuego ardiente, de modo que no podía mirarlas."),
                VerseEntry("14:20", "La Gran Gloria estaba sentada sobre él; sus vestiduras brillaban más que el sol y eran más blancas que la nieve."),
                VerseEntry("14:21", "Ningún ángel podía entrar ni contemplar su rostro, a causa de su magnificencia y gloria; ningún ser de carne podía verlo."),
                VerseEntry("14:22", "El fuego ardiente lo rodeaba y un gran fuego estaba delante de él. Nadie de los que lo rodeaban podía acercarse. Diez mil veces diez mil estaban ante él, pero no necesitaba consejero alguno."),
                VerseEntry("14:23", "Los santísimos que se acercaban a él no se apartaban de su presencia ni de noche ni de día."),
                VerseEntry("14:24", "Hasta entonces yo había permanecido postrado, temblando y con el rostro en tierra. El Señor me llamó con su propia boca y dijo: «Ven aquí, Enoc, y escucha mi palabra»."),
                VerseEntry("14:25", "[Uno de los santos se acercó y me despertó;] él me hizo levantar y aproximarme a la puerta, mientras yo mantenía el rostro inclinado.")
            )),
        ChapterEntry(15, "La respuesta sobre los gigantes y los espíritus", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "Charles encierra 15:10 entre corchetes cuadrados: es una cláusula que debe mantenerse separada del texto principal hasta verificar su transmisión. En 15:9 y 15:11 hay suplementos editoriales; «pero sienten hambre» aparece entre signos angulares. El vocabulario sobre la procedencia de los espíritus es teológicamente complejo y no debe armonizarse con doctrinas posteriores. Rylands Ethiopic MS 23, fol. 3v cols. a–b. Fuentes: Dillmann 1851, cap. 15; Charles 1917, 15:1–12; Theosis Library, §15, Rylands Ethiopic MS 23, fol. 3v cols. a–b. Documento editorial: docs/chapters/15.md",
            listOf(
                VerseEntry("15:1", "Él me respondió y dijo: «Escucha; no temas, Enoc, hombre justo y escriba de justicia. Acércate y escucha mi voz»."),
                VerseEntry("15:2", "«Ve y di a los Vigilantes del cielo que te enviaron para interceder por ellos: vosotros debéis interceder por los seres humanos, y no los seres humanos por vosotros»."),
                VerseEntry("15:3", "«¿Por qué abandonasteis el cielo elevado, santo y eterno, os acostasteis con mujeres, os contaminasteis con las hijas de los hombres, tomasteis esposas y actuasteis como los hijos de la tierra, engendrando gigantes como hijos?»"),
                VerseEntry("15:4", "«Aunque erais santos, espirituales y vivíais una vida eterna, os contaminasteis con la sangre de las mujeres y engendrasteis hijos mediante la sangre de la carne. Deseasteis la carne y la sangre como hacen quienes mueren y perecen»."),
                VerseEntry("15:5", "«Por eso concedí a los seres humanos mujeres, para que se unieran a ellas y engendraran hijos, y para que no faltara nada de lo necesario sobre la tierra»."),
                VerseEntry("15:6", "«Vosotros, en cambio, erais espirituales, vivíais la vida eterna y erais inmortales por todas las generaciones del mundo»."),
                VerseEntry("15:7", "«Por eso no os asigné esposas, pues la morada de los seres espirituales del cielo está en el cielo»."),
                VerseEntry("15:8", "«Ahora los gigantes, nacidos de espíritu y carne, serán llamados espíritus malignos sobre la tierra, y su morada estará en la tierra»."),
                VerseEntry("15:9", "«Los espíritus malignos proceden de sus cuerpos; nacieron de los seres humanos, pero su origen primero procede de los santos Vigilantes. [Serán espíritus malignos sobre la tierra y así serán llamados]»."),
                VerseEntry("15:10", "[«Los espíritus del cielo tendrán su morada en el cielo; los espíritus de la tierra, nacidos sobre la tierra, tendrán su morada en la tierra».]"),
                VerseEntry("15:11", "«Los espíritus de los gigantes afligen, oprimen, destruyen, atacan, combaten y causan devastación sobre la tierra. Producen dificultades; no comen alimento, [pero sienten hambre], tienen sed y provocan tropiezos»."),
                VerseEntry("15:12", "«Estos espíritus se levantarán contra los hijos de los hombres y contra las mujeres, porque de ellos proceden».")
            )),
        ChapterEntry(16, "La sentencia final sobre los Vigilantes", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "En 16:1 Charles añade entre corchetes angulares «de los gigantes» y «juicio», y marca «gran» como suplemento; la traducción mantiene el sentido con advertencia. En 16:2 «antes» está marcado como suplemento. En 16:3 «todos» también es aclaración editorial. La numeración de Charles es 16:1–4. Rylands Ethiopic MS 23, fol. 3v col. b. Fuentes: Dillmann 1851, cap. 16; Charles 1917, 16:1–4; Theosis Library, §16, Rylands Ethiopic MS 23, fol. 3v col. b. Documento editorial: docs/chapters/16.md",
            listOf(
                VerseEntry("16:1", "«Desde los días de la matanza, destrucción y muerte de los gigantes, los espíritus que salieron de sus cuerpos causarán destrucción sin recibir juicio; así seguirán destruyendo hasta el día de la consumación, el gran juicio en que llegará a su término la era y se cumplirá plenamente la sentencia contra los Vigilantes y los impíos»."),
                VerseEntry("16:2", "«Y ahora, respecto de los Vigilantes que te enviaron para que intercedieras por ellos, que antes estuvieron en el cielo…»"),
                VerseEntry("16:3", "«Vosotros estabais en el cielo, pero todavía no se os habían revelado todos los misterios. Conocisteis cosas sin valor y, por la dureza de vuestro corazón, las disteis a conocer a las mujeres; mediante esos misterios, mujeres y hombres realizan mucho mal sobre la tierra»."),
                VerseEntry("16:4", "«Decidles, por tanto: “No tendréis paz”».")
            )),
        ChapterEntry(17, "El primer viaje de Enoc", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "Charles marca como suplementos «los depósitos de las estrellas», la espada de fuego y otros elementos en 17:3; en 17:6 su traducción incluye una reconstrucción («gran río y gran oscuridad»). Se conservan entre corchetes. El capítulo describe geografía visionaria, no un mapa físico moderno. Rylands Ethiopic MS 23, fol. 3v col. b. Fuentes: Dillmann 1851, cap. 17; Charles 1917, 17:1–8; Theosis Library, §17, Rylands Ethiopic MS 23, fol. 3v col. b. Documento editorial: docs/chapters/17.md",
            listOf(
                VerseEntry("17:1", "Me llevaron a un lugar donde los que allí estaban eran como fuego ardiente; cuando querían, aparecían con forma humana."),
                VerseEntry("17:2", "Me condujeron a una región de oscuridad y a una montaña cuya cima llegaba hasta el cielo."),
                VerseEntry("17:3", "Vi los lugares de las luminarias [y los depósitos de las estrellas], y los del trueno; en las profundidades extremas vi un arco de fuego, flechas, su carcaj, [una espada de fuego] y todos los relámpagos."),
                VerseEntry("17:4", "Me llevaron hasta las aguas vivas y hasta el fuego del occidente, que recibe todas las puestas del sol."),
                VerseEntry("17:5", "Llegué a un río de fuego, cuyo fuego fluía como agua y desembocaba en el gran mar hacia el occidente."),
                VerseEntry("17:6", "Vi los grandes ríos y llegué a la gran [corriente] y a la gran oscuridad; fui al lugar por donde no camina carne alguna."),
                VerseEntry("17:7", "Vi las montañas de la oscuridad del invierno y el lugar de donde fluyen todas las aguas del abismo."),
                VerseEntry("17:8", "Vi las desembocaduras de todos los ríos de la tierra y la boca del abismo.")
            )),
        ChapterEntry(18, "Los depósitos de los vientos y las estrellas transgresoras", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "Charles marca múltiples cláusulas como suplementos: 18:2–3, 18:5, 18:11 y 18:16. En 18:7 la identificación de las piedras preciosas depende de términos antiguos cuya equivalencia mineralógica no es segura; se conserva la transliteración tradicional cuando es necesario. El capítulo está en Rylands Ethiopic MS 23, fol. 3v cols. b–c. Fuentes: Dillmann 1851, cap. 18; Charles 1917, 18:1–16; Theosis Library, §18, Rylands Ethiopic MS 23, fol. 3v cols. b–c. Documento editorial: docs/chapters/18.md",
            listOf(
                VerseEntry("18:1", "Vi los depósitos de todos los vientos y cómo Dios había dispuesto mediante ellos toda la creación y los fundamentos firmes de la tierra."),
                VerseEntry("18:2", "Vi la piedra angular de la tierra y los cuatro vientos que sostienen [la tierra y] la bóveda del cielo."),
                VerseEntry("18:3", "[Vi cómo los vientos extienden las bóvedas del cielo] y permanecen entre el cielo y la tierra; [estos son los pilares del cielo]."),
                VerseEntry("18:4", "Vi los vientos del cielo que hacen girar el recorrido del sol y conducen a su ocaso a todas las estrellas."),
                VerseEntry("18:5", "Vi los vientos de la tierra que transportan las nubes; vi [los caminos de los ángeles] y, en el extremo de la tierra, la bóveda del cielo que está arriba."),
                VerseEntry("18:6", "Seguí adelante y vi un lugar que arde día y noche, donde hay siete montañas de piedras magníficas: tres hacia el oriente y tres hacia el sur."),
                VerseEntry("18:7", "De las montañas orientales, una era de piedra de colores, otra de perla y otra de jacinto; las del sur eran de piedra roja."),
                VerseEntry("18:8", "La montaña central se elevaba hasta el cielo, como el trono de Dios; era de alabastro y la parte superior del trono era de zafiro."),
                VerseEntry("18:9", "Vi un fuego ardiente que se extendía por todas las montañas."),
                VerseEntry("18:10", "Más allá de aquellas montañas había una región que marcaba el extremo de la gran tierra; allí terminaban los cielos."),
                VerseEntry("18:11", "Vi un abismo profundo, con columnas [de fuego celeste]; vi columnas de fuego que caían, inconmensurables tanto en altura como en profundidad."),
                VerseEntry("18:12", "Más allá del abismo vi un lugar sin bóveda celeste encima ni tierra firme debajo; no había agua ni aves, sino un paraje desolado y terrible."),
                VerseEntry("18:13", "Vi allí siete estrellas semejantes a grandes montañas ardientes. Cuando pregunté por ellas…"),
                VerseEntry("18:14", "El ángel dijo: «Este lugar es el límite del cielo y de la tierra; se ha convertido en prisión para las estrellas y las huestes del cielo»."),
                VerseEntry("18:15", "«Las estrellas que ruedan sobre el fuego son las que transgredieron el mandato del Señor desde el comienzo de su aparición, porque no salieron en los tiempos que les correspondían»."),
                VerseEntry("18:16", "«Él se irritó contra ellas y las ató hasta el tiempo en que se complete su culpa, [durante diez mil años]».")
            )),
        ChapterEntry(19, "El destino de los ángeles transgresores", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "En 19:1 Charles marca «como dioses» y «hasta el día de» como suplementos. La expresión relativa a los espíritus que adoptan formas y extravían a la humanidad debe leerse dentro de la cosmología del texto, sin imponerle categorías demonológicas posteriores. El término «sirenas» traduce una figura híbrida de la tradición antigua y no debe sustituirse sin nota por otra criatura. Rylands Ethiopic MS 23, fol. 3v col. c–4r col. a. Fuentes: Dillmann 1851, cap. 19; Charles 1917, 19:1–3; Theosis Library, §19, Rylands Ethiopic MS 23, fol. 3v col. c–4r col. a. Documento editorial: docs/chapters/19.md",
            listOf(
                VerseEntry("19:1", "Uriel me dijo: «Aquí permanecerán los ángeles que se unieron a las mujeres. Sus espíritus, adoptando muchas formas, corrompen a los seres humanos y los extravían hasta hacerlos ofrecer sacrificios a los demonios como si fueran dioses. Permanecerán aquí hasta el gran juicio, en el que serán juzgados y llevados a su fin»."),
                VerseEntry("19:2", "«También las mujeres de los ángeles que se desviaron se convertirán en sirenas»."),
                VerseEntry("19:3", "Yo, Enoc, fui el único que vio la visión, los confines de todas las cosas; ningún ser humano verá lo que yo he visto.")
            )),
        ChapterEntry(20, "Los siete ángeles santos", "Traducción de trabajo revisada con Dillmann 1851 y Charles 1917 · aparato crítico pendiente",
            "Texto traducido y organizado versículo por versículo según la numeración editorial de Charles. Véase la nota textual para suplementos, reconstrucciones y dificultades.",
            "Charles imprime ocho versículos: una introducción (20:1) y siete nombres con sus funciones (20:2–8). El ge'ez de Dillmann confirma los siete nombres, pero las funciones de Ragüel, Miguel y Saraqael requieren atención: Charles marca «toma venganza» con † y «y» / «sobre el caos» como suplementos en la lista. El sentido de la última función de Remiel se traduce como «los que se levantan», con posible referencia a la resurrección. Las transliteraciones de los nombres no son uniformes entre ediciones. Rylands Ethiopic MS 23, fol. 4r col. a. Fuentes: Dillmann 1851, cap. 20; Charles 1917, 20:1–8; Theosis Library, §20, Rylands Ethiopic MS 23, fol. 4r col. a. Documento editorial: docs/chapters/20.md",
            listOf(
                VerseEntry("20:1", "Estos son los nombres de los santos ángeles que velan:"),
                VerseEntry("20:2", "Uriel, uno de los santos ángeles, encargado del mundo y del Tártaro."),
                VerseEntry("20:3", "Rafael, uno de los santos ángeles, encargado de los espíritus de los seres humanos."),
                VerseEntry("20:4", "Ragüel, uno de los santos ángeles, que [ejerce venganza sobre] el mundo de las luminarias."),
                VerseEntry("20:5", "Miguel, uno de los santos ángeles, encargado de la mejor parte de la humanidad [y del caos]."),
                VerseEntry("20:6", "Saraqael, uno de los santos ángeles, encargado de los espíritus de los seres humanos que pecan en el espíritu."),
                VerseEntry("20:7", "Gabriel, uno de los santos ángeles, encargado del Paraíso, de las serpientes y de los querubines."),
                VerseEntry("20:8", "Remiel, uno de los santos ángeles, a quien Dios puso al frente de los que se levantan [o resucitan].")
            )),
        ChapterEntry(21, "Lugares de juicio", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "En su recorrido, Enoc contempla un espacio terrible y desolado. Observa una región donde no hay cielo visible ni tierra firme, sino un vacío que provoca temor. Allí distingue estrellas que parecen estar encadenadas y pregunta por qué permanecen en ese estado. Un mensajero le explica que son seres celestes que transgredieron el orden establecido y aguardan el juicio. Enoc comprende que la rebelión contra el orden divino no queda sin consecuencia.",
            "La descripción y la identificación de los seres deben cotejarse con las variantes de traducción y los testimonios manuscritos. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("21:unidad completa", "En su recorrido, Enoc contempla un espacio terrible y desolado. Observa una región donde no hay cielo visible ni tierra firme, sino un vacío que provoca temor. Allí distingue estrellas que parecen estar encadenadas y pregunta por qué permanecen en ese estado. Un mensajero le explica que son seres celestes que transgredieron el orden establecido y aguardan el juicio. Enoc comprende que la rebelión contra el orden divino no queda sin consecuencia."))),

        ChapterEntry(22, "Las moradas de las almas", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc llega a una montaña y descubre un lugar profundo con espacios separados. Un guía le muestra las cavidades donde esperan las almas de quienes han muerto. Cada grupo permanece apartado hasta el momento de la sentencia, y Enoc pregunta por las diferencias entre sus destinos. La visión presenta la espera como un estado anterior al juicio final: las vidas y sus actos no se confunden, y la justicia aún habrá de manifestarse plenamente.",
            "Las divisiones, nombres y descripciones de las cavidades varían entre versiones; verificar antes de fijar el texto definitivo. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("22:unidad completa", "Enoc llega a una montaña y descubre un lugar profundo con espacios separados. Un guía le muestra las cavidades donde esperan las almas de quienes han muerto. Cada grupo permanece apartado hasta el momento de la sentencia, y Enoc pregunta por las diferencias entre sus destinos. La visión presenta la espera como un estado anterior al juicio final: las vidas y sus actos no se confunden, y la justicia aún habrá de manifestarse plenamente."))),

        ChapterEntry(23, "El fuego del extremo", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc observa un fuego que se extiende hasta un límite remoto. Pregunta por su origen y por la fuerza que lo mantiene. El paisaje expresa la magnitud de un juicio que supera la comprensión humana y el guía le revela que ese lugar forma parte del orden reservado para el tiempo señalado.",
            "Capítulo breve en algunas tradiciones textuales; su redacción y alcance requieren cotejo. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("23:unidad completa", "Enoc observa un fuego que se extiende hasta un límite remoto. Pregunta por su origen y por la fuerza que lo mantiene. El paisaje expresa la magnitud de un juicio que supera la comprensión humana y el guía le revela que ese lugar forma parte del orden reservado para el tiempo señalado."))),

        ChapterEntry(24, "La montaña de fuego y las montañas escogidas", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc contempla montañas extraordinarias, algunas de piedra preciosa y otras asociadas al fuego. El guía le muestra una montaña cuya apariencia y altura la distinguen, y le explica que ciertos lugares han sido preparados para un propósito sagrado. La visión combina geografía imposible, esplendor mineral y la idea de que la creación contiene espacios apartados para el juicio y la revelación.",
            "La secuencia de montañas y sus materiales debe cotejarse con una edición textual fiable. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("24:unidad completa", "Enoc contempla montañas extraordinarias, algunas de piedra preciosa y otras asociadas al fuego. El guía le muestra una montaña cuya apariencia y altura la distinguen, y le explica que ciertos lugares han sido preparados para un propósito sagrado. La visión combina geografía imposible, esplendor mineral y la idea de que la creación contiene espacios apartados para el juicio y la revelación."))),

        ChapterEntry(25, "El árbol de la vida", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc ve una montaña central y, cerca de ella, un árbol cuya fragancia y belleza no se parecen a las de ningún árbol conocido. El guía explica que su fruto está reservado para los justos en el tiempo futuro, cuando la vida y la alegría serán restauradas. El árbol se convierte en imagen de esperanza: aquello que fue inaccesible será concedido a quienes permanezcan fieles, en el mundo renovado que la visión anuncia.",
            "La descripción del árbol y su ubicación se deben revisar contra las variantes; no asumir equivalencias directas con otros textos bíblicos sin nota comparativa. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("25:unidad completa", "Enoc ve una montaña central y, cerca de ella, un árbol cuya fragancia y belleza no se parecen a las de ningún árbol conocido. El guía explica que su fruto está reservado para los justos en el tiempo futuro, cuando la vida y la alegría serán restauradas. El árbol se convierte en imagen de esperanza: aquello que fue inaccesible será concedido a quienes permanezcan fieles, en el mundo renovado que la visión anuncia."))),

        ChapterEntry(26, "El valle bendecido", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc es conducido hacia una región cercana a las montañas y contempla un valle amplio. El guía le explica que ese lugar será asociado con la reunión de quienes buscan justicia y con la bendición que llegará cuando el orden sea restaurado. La geografía de la visión enlaza el paisaje con la esperanza de un futuro renovado.",
            "La identificación geográfica con Jerusalén y sus alrededores depende de la tradición textual y de la interpretación; debe anotarse sin convertirla en certeza. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("26:unidad completa", "Enoc es conducido hacia una región cercana a las montañas y contempla un valle amplio. El guía le explica que ese lugar será asociado con la reunión de quienes buscan justicia y con la bendición que llegará cuando el orden sea restaurado. La geografía de la visión enlaza el paisaje con la esperanza de un futuro renovado."))),
        ChapterEntry(27, "El valle de la condena", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc ve otro valle, apartado y sombrío. El mensajero le explica que será destinado a quienes persistieron en la injusticia y que allí se hará visible el juicio. El lugar contrasta con el valle de bendición descrito anteriormente: ambos funcionan como señales de las consecuencias de la conducta humana.",
            "Confirmar los nombres tradicionales del valle y su relación con topónimos conocidos antes de cerrar la edición. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("27:unidad completa", "Enoc ve otro valle, apartado y sombrío. El mensajero le explica que será destinado a quienes persistieron en la injusticia y que allí se hará visible el juicio. El lugar contrasta con el valle de bendición descrito anteriormente: ambos funcionan como señales de las consecuencias de la conducta humana."))),
        ChapterEntry(28, "El viaje hacia el oriente", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc continúa su viaje y llega a una región desierta. Observa árboles y vegetación en un paisaje que parece ocultar una abundancia inesperada. El guía le señala la continuidad de la creación y la belleza que permanece incluso en lugares remotos.",
            "Paráfrasis de trabajo; revisar la descripción botánica y el itinerario en una fuente cotejada. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("28:unidad completa", "Enoc continúa su viaje y llega a una región desierta. Observa árboles y vegetación en un paisaje que parece ocultar una abundancia inesperada. El guía le señala la continuidad de la creación y la belleza que permanece incluso en lugares remotos."))),
        ChapterEntry(29, "Aromas y árboles extraordinarios", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc descubre árboles cuyas resinas y aromas son diferentes de los que conoce. El guía le muestra sustancias fragantes y le explica que la región contiene plantas singulares, presentadas como parte de la riqueza de la creación.",
            "Los nombres de resinas y especies pueden variar según traducción; evitar identificaciones botánicas modernas sin respaldo. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("29:unidad completa", "Enoc descubre árboles cuyas resinas y aromas son diferentes de los que conoce. El guía le muestra sustancias fragantes y le explica que la región contiene plantas singulares, presentadas como parte de la riqueza de la creación."))),
        ChapterEntry(30, "El territorio de los aromas", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "El recorrido de Enoc prosigue por un territorio donde crecen árboles y plantas de fragancia intensa. La visión describe la naturaleza como un tesoro que el viajero descubre poco a poco; cada paisaje amplía su comprensión de la creación y de sus maravillas.",
            "El capítulo debe cotejarse con la secuencia exacta del viaje y las variantes de nombres de plantas en los manuscritos y traducciones. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("30:unidad completa", "El recorrido de Enoc prosigue por un territorio donde crecen árboles y plantas de fragancia intensa. La visión describe la naturaleza como un tesoro que el viajero descubre poco a poco; cada paisaje amplía su comprensión de la creación y de sus maravillas."))),
        ChapterEntry(31, "Especias y maravillas de la tierra", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc atraviesa un territorio donde crecen árboles y plantas de aromas singulares. El paisaje le revela una riqueza que no había visto, y el guía le explica que esas maravillas forman parte de la creación dispuesta para su tiempo y propósito.",
            "Confirmar la secuencia, especies y nombres de sustancias aromáticas en el texto base. La paráfrasis no pretende reconstruir detalles ausentes. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("31:unidad completa", "Enoc atraviesa un territorio donde crecen árboles y plantas de aromas singulares. El paisaje le revela una riqueza que no había visto, y el guía le explica que esas maravillas forman parte de la creación dispuesta para su tiempo y propósito."))),
        ChapterEntry(32, "El jardín de justicia y el árbol del conocimiento", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "El viaje lleva a Enoc a un jardín extraordinario. Allí contempla árboles de gran belleza y, entre ellos, el árbol asociado al conocimiento. La visión recuerda el jardín primordial y presenta un espacio que guarda memoria de los comienzos, pero también anuncia la revelación que Enoc recibe durante su recorrido.",
            "La relación con Génesis debe tratarse como paralelo literario, no como equivalencia automática. Revisar la identificación de árboles y el orden narrativo en la fuente. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("32:unidad completa", "El viaje lleva a Enoc a un jardín extraordinario. Allí contempla árboles de gran belleza y, entre ellos, el árbol asociado al conocimiento. La visión recuerda el jardín primordial y presenta un espacio que guarda memoria de los comienzos, pero también anuncia la revelación que Enoc recibe durante su recorrido."))),
        ChapterEntry(33, "Las puertas de los extremos", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc contempla los límites del mundo y las puertas por las que los astros recorren sus caminos. Un guía le muestra direcciones y regiones que superan la experiencia humana. El viajero escucha que el orden de los cielos y la tierra está establecido y no es arbitrario.",
            "Este capítulo forma parte del ciclo de visiones geográficas; precisar la estructura y los nombres según edición elegida. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("33:unidad completa", "Enoc contempla los límites del mundo y las puertas por las que los astros recorren sus caminos. Un guía le muestra direcciones y regiones que superan la experiencia humana. El viajero escucha que el orden de los cielos y la tierra está establecido y no es arbitrario."))),
        ChapterEntry(34, "El norte y sus regiones", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc se dirige hacia el norte y observa una región de límites y fenómenos que el guía le describe. La visión presenta el mundo como una geografía ordenada, con entradas y salidas asignadas a los elementos y a los movimientos celestes.",
            "No convertir la cosmografía antigua en descripción científica moderna. Cotejar los detalles del capítulo. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("34:unidad completa", "Enoc se dirige hacia el norte y observa una región de límites y fenómenos que el guía le describe. La visión presenta el mundo como una geografía ordenada, con entradas y salidas asignadas a los elementos y a los movimientos celestes."))),
        ChapterEntry(35, "El occidente y sus puertas", "Paráfrasis literaria · cotejo versículo por versículo pendiente",
            "Enoc continúa contemplando las fronteras del mundo y sus accesos. El recorrido por el occidente completa parte de la descripción de regiones y puertas, y refuerza el tema de un cosmos cuyos movimientos obedecen a un orden revelado.",
            "Borrador de lectura; confirmar correspondencia exacta con el capítulo y su orden en la edición de referencia antes de editarlo definitivamente. Paráfrasis preliminar; no es traducción crítica.",
            listOf(VerseEntry("35:unidad completa", "Enoc continúa contemplando las fronteras del mundo y sus accesos. El recorrido por el occidente completa parte de la descripción de regiones y puertas, y refuerza el tema de un cosmos cuyos movimientos obedecen a un orden revelado."))),

    ) + LaterEnocContent36_50.chapters + LaterEnocContent51_65.chapters + LaterEnocContent66_80.chapters + LaterEnocContent81_95.chapters + LaterEnocContent96_108.chapters
}
